#!/usr/bin/env bash
# Every leaf that depends on its own `generated/` must be REGENERABLE.
#
# `scripts/regenerate-bindings.sh` finds work by globbing tracked `package.xml`
# files (`git ls-files … '**/package.xml'`). A leaf whose Cargo.toml names
# `path = "generated/<pkg>"` but which has no `package.xml` is invisible to it:
# `just generate-bindings` walks straight past, and the only copy of its
# bindings is whatever someone generated by hand, once.
#
# That is not hypothetical. Eight `nros-tests/bins` leaves sat like that with
# their `generated/` committed, and by the time anyone looked the trees had
# frozen several phases back — they were still missing the phase-303 W4 (#0267)
# XCDR2 DHEADER wrap that every other message crate in the repo had. The bins
# built and their tests passed, against message code that no longer matched the
# codegen. Nothing could have noticed: a stale tree and a fresh one look
# identical to `cargo build`.
#
# `just clean-bindings` makes it worse — it DELETES `generated/` under
# nros-bench / nros-tests/bins / nros-smoke, so for an invisible leaf the pair
# `clean-bindings` + `generate-bindings` is destructive, recoverable only from
# git.
#
# So: if a leaf consumes `generated/`, the regenerator has to be able to see it.
set -uo pipefail

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$repo_root"

violations=0
while IFS= read -r manifest; do
    dir="$(dirname "$manifest")"
    [ -f "$dir/package.xml" ] && continue
    if [ "$violations" -eq 0 ]; then
        echo "check-generated-leaf-regenerable: leaves consuming generated/ with no package.xml:" >&2
    fi
    echo "  $dir" >&2
    violations=$((violations + 1))
done < <(grep -rlE 'path = "generated/' --include=Cargo.toml packages examples 2>/dev/null | sort)

if [ "$violations" -ne 0 ]; then
    {
        echo
        echo "  Each of these names a message crate under its own generated/, but"
        echo "  scripts/regenerate-bindings.sh globs tracked package.xml files, so it"
        echo "  never regenerates them — their bindings freeze at whenever they were"
        echo "  last produced by hand, silently."
        echo
        echo "  Add a package.xml declaring the interface packages it generates FROM:"
        echo "      <depend>std_msgs</depend>"
        echo "  then run: just generate-bindings"
    } >&2
    exit 1
fi

echo "check-generated-leaf-regenerable: OK (every generated/ consumer is visible to the regenerator)"
